// Independent diagnostic oracle; none of the archived prototype bodies change.
#include "PhysicalCoverage.h"
#include <cuda_runtime.h>
#include <cmath>
#include <stdexcept>
namespace prototype_io { namespace {
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct DeviceData {int w,a,ns,nt;double L[3],rc2,dOE,qw[4],ao,bo;const double*q,*aoS,*boS,*aa,*bb;const int*type,*rows,*neighbors;};
struct Counts {unsigned long long required[3],missing[3],extra[3];int firstKind,firstI,firstJ,image[3];};
__device__ size_t pairIndex(int i,int j,int n){return size_t(i)*(2*size_t(n)-i-1)/2+(j-i-1);}
__device__ double3 point(const double*x,int p){return make_double3(x[3*p],x[3*p+1],x[3*p+2]);}
__device__ double3 sub(double3 a,double3 b){return make_double3(a.x-b.x,a.y-b.y,a.z-b.z);}
__device__ double dot(double3 a){return a.x*a.x+a.y*a.y+a.z*a.z;}
__device__ double3 anchor(DeviceData d,const double*x,int i){return point(x,i<d.w?d.a+d.ns*i:i-d.w);}
__device__ int3 nearest(double3 a,double3 b,DeviceData d){return make_int3(int(nearbyint((a.x-b.x)/d.L[0])),int(nearbyint((a.y-b.y)/d.L[1])),int(nearbyint((a.z-b.z)/d.L[2])));}
__device__ int imageBit(int3 n,int3 base){int a=n.x-base.x,b=n.y-base.y,c=n.z-base.z;if(abs(a)>1||abs(b)>1||abs(c)>1)return -1;return (a+1)+3*(b+1)+9*(c+1);}
__global__ void waterSites(DeviceData d,const double*x,double3*out){int w=blockIdx.x*blockDim.x+threadIdx.x;if(w>=d.w)return;int p=d.a+d.ns*w;double3 o=point(x,p),h=point(x,p+1),j=point(x,p+2);out[4*w]=o;out[4*w+1]=h;out[4*w+2]=j;if(d.ns==4){double3 u=sub(h,o),v=sub(j,o);double ru=sqrt(dot(u)),rv=sqrt(dot(v));double3 b=make_double3(u.x/ru+v.x/rv,u.y/ru+v.y/rv,u.z/ru+v.z/rv);double scale=d.dOE/sqrt(dot(b));out[4*w+3]=make_double3(o.x+scale*b.x,o.y+scale*b.y,o.z+scale*b.z);}}
__global__ void markList(DeviceData d,SessionDeviceView v,int kind,const double*x,unsigned*bits,Counts*c){int g=blockIdx.x;if(g>=v.classes[kind].groups)return;auto l=v.classes[kind];const int*oi=kind==0?v.waterOrder:v.atomOrder;const int*oj=kind==2?v.atomOrder:v.waterOrder;const int4*si=(const int4*)(kind==0?v.waterShifts:v.atomShifts);const int4*sj=(const int4*)(kind==2?v.atomShifts:v.waterShifts);auto entries=(const int2*)l.innerEntries;
 for(int e=threadIdx.x;e<l.innerCount[g];e+=blockDim.x){int2 en=entries[size_t(l.blockStart[g])*64+e];int j0=oj[en.x];if(j0<0)continue;int j=j0+(kind==2?d.w:0);int4 js=sj[j0];for(int b=0;b<16;++b)if(unsigned(en.y)&(1u<<b)){int i0=oi[16*g+b];if(i0<0)continue;int i=i0+(kind?d.w:0);if(i==j)continue;int4 is=si[i0];int3 n=make_int3(int((unsigned(en.y)>>16)&15)-4-is.x+js.x,int((unsigned(en.y)>>20)&15)-4-is.y+js.y,int((unsigned(en.y)>>24)&15)-4-is.z+js.z);int lo=i,hi=j;if(lo>hi){lo=j;hi=i;n=make_int3(-n.x,-n.y,-n.z);}int3 base=nearest(anchor(d,x,lo),anchor(d,x,hi),d);int bit=imageBit(n,base);if(bit>=0)atomicOr(bits+pairIndex(lo,hi,d.w+d.a),1u<<bit);else atomicAdd(c->extra+kind,1ull);}}
}
__device__ bool excluded(DeviceData d,int i,int j){for(int p=d.rows[i];p<d.rows[i+1];++p)if(d.neighbors[p]==j)return true;return false;}
__global__ void inspect(DeviceData d,const double*x,const double3*ws,const unsigned*bits,Counts*c){int i=blockIdx.x*blockDim.x+threadIdx.x,j=blockIdx.y*blockDim.y+threadIdx.y,n=d.w+d.a;if(i>=j||j>=n)return;int kind=j<d.w?0:i<d.w?1:2;unsigned required=0;int3 base=nearest(anchor(d,x,i),anchor(d,x,j),d);
 // SW canonical index is water then atom; SS excludes graph neighbors.
 bool skip=kind==2&&(excluded(d,i-d.w,j-d.w)||excluded(d,j-d.w,i-d.w));
 if(!skip){int ni=i<d.w?d.ns:1,nj=j<d.w?d.ns:1;for(int s=0;s<ni;++s)for(int t=0;t<nj;++t){double qi=i<d.w?d.qw[s]:d.q[i-d.w],qj=j<d.w?d.qw[t]:d.q[j-d.w];bool lj=false;if(kind==0)lj=s==0&&t==0&&(d.ao!=0||d.bo!=0);else if(kind==1)lj=s==0&&(d.aoS[j-d.w]!=0||d.boS[j-d.w]!=0);else{int k=d.type[i-d.w]*d.nt+d.type[j-d.w];lj=d.aa[k]!=0||d.bb[k]!=0;}if(!lj&&(qi==0||qj==0))continue;double3 a=i<d.w?ws[4*i+s]:point(x,i-d.w),b=j<d.w?ws[4*j+t]:point(x,j-d.w);int3 image=nearest(a,b,d);double3 r=make_double3(a.x-b.x-image.x*d.L[0],a.y-b.y-image.y*d.L[1],a.z-b.z-image.z*d.L[2]);if(dot(r)<d.rc2){int bit=imageBit(image,base);if(bit>=0)required|=1u<<bit;else{atomicAdd(c->missing+kind,1ull);}}}}
 unsigned present=bits[pairIndex(i,j,n)],missing=required&~present;atomicAdd(c->required+kind,(unsigned long long)__popc(required));atomicAdd(c->missing+kind,(unsigned long long)__popc(missing));atomicAdd(c->extra+kind,(unsigned long long)__popc(present&~required));if(missing&&atomicCAS(&c->firstKind,-1,kind)==-1){c->firstI=i;c->firstJ=j;int b=__ffs(missing)-1;c->image[0]=base.x+b%3-1;c->image[1]=base.y+(b/3)%3-1;c->image[2]=base.z+b/9-1;}}
}
PhysicalCoverageResult verifySessionPhysical(Session*s,const double*x){auto h=sessionPhysicalData(s);DeviceData d{};d.w=h.waters;d.a=h.atoms;d.ns=h.sites;d.nt=h.types;for(int k=0;k<3;++k)d.L[k]=h.cell[k];for(int k=0;k<4;++k)d.qw[k]=h.qWater[k];d.rc2=h.cutoff*h.cutoff;d.dOE=h.dOE;d.ao=h.aOO;d.bo=h.bOO;d.rows=h.exRows;d.neighbors=h.exNeighbors;
 std::vector<void*>alloc;auto allocate=[&](size_t bytes){void*p=nullptr;ck(cudaMalloc(&p,bytes?bytes:1));alloc.push_back(p);return p;};auto upload=[&](const auto&v){using T=typename std::decay_t<decltype(v)>::value_type;auto*p=allocate(v.size()*sizeof(T));if(!v.empty())ck(cudaMemcpy(p,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return p;};
 try{d.q=(double*)upload(h.charges);d.aoS=(double*)upload(h.aOS);d.boS=(double*)upload(h.bOS);d.aa=(double*)upload(h.aSS);d.bb=(double*)upload(h.bSS);d.type=(int*)upload(h.atomTypes);int n=d.w+d.a;size_t count=size_t(n)*(n-1)/2;auto*bits=(unsigned*)allocate(4*count);ck(cudaMemset(bits,0,4*count));auto*sites=(double3*)allocate(4*size_t(d.w)*sizeof(double3));auto*c=(Counts*)allocate(sizeof(Counts));Counts initial{};initial.firstKind=-1;ck(cudaMemcpy(c,&initial,sizeof(initial),cudaMemcpyHostToDevice));waterSites<<<(d.w+127)/128,128>>>(d,x,sites);auto v=sessionDeviceView(s);for(int k=0;k<3;++k)if(v.classes[k].groups)markList<<<v.classes[k].groups,128>>>(d,v,k,x,bits,c);inspect<<<dim3((n+15)/16,(n+15)/16),dim3(16,16)>>>(d,x,sites,bits,c);ck(cudaGetLastError());Counts out{};ck(cudaMemcpy(&out,c,sizeof(out),cudaMemcpyDeviceToHost));PhysicalCoverageResult result{};for(int k=0;k<3;++k){result.required[k]=out.required[k];result.missing[k]=out.missing[k];result.extra[k]=out.extra[k];result.firstImage[k]=out.image[k];}result.firstKind=out.firstKind;result.firstI=out.firstI;result.firstJ=out.firstJ;for(void*p:alloc)cudaFree(p);return result;}catch(...){for(void*p:alloc)cudaFree(p);throw;}}
}
